        triton.Config({'XBLOCK': 1,  'YBLOCK': 256}, num_warps=8),
        triton.Config({'XBLOCK': 4,  'YBLOCK': 64},  num_warps=4),
        # ... more configs ...
    ],
    key=['ynumel', 'xnumel'],
)
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    # memory-latency-bound body: load, compute, store
    tmp0 = tl.load(in_ptr + offset, mask)
    tl.store(out_ptr + offset2, tmp0, mask, eviction_policy='evict_first')

